script.setup:
// Bezier.js does the curve math: offset curves, outlines, curve/curve intersections and
// projecting the pointer onto the nearest curve. The control points drift; drag them to pin.
const { Bezier } = await ctx.utils.import("https://esm.sh/bezier-js@6.1.4");
const gl = ctx.gl;
gl.getExtension("EXT_color_buffer_float");
const flat = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec4 a_color;
uniform vec2 u_px; out vec4 v_color;
void main(){ v_color = a_color; gl_Position = vec4(a_position / u_px * 2.0 - 1.0, 0.0, 1.0); }`, `#version 300 es
precision highp float; in vec4 v_color; out vec4 outColor;
void main(){ outColor = v_color; }`);
const vao = gl.createVertexArray(), vbo = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 24, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 4, gl.FLOAT, false, 24, 8);
gl.bindVertexArray(null);
const kit = {
  // Draws a flat (x, y, r, g, b, a) triangle list.
  draw(arr) {
    if (!arr.length) return;
    gl.useProgram(flat);
    ctx.utils.setUniforms(flat, { u_px: ctx.resolution });
    gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(arr), gl.DYNAMIC_DRAW);
    gl.drawArrays(gl.TRIANGLES, 0, arr.length / 6);
    gl.bindVertexArray(null);
  },
  // Signed triangle fan: inside a closed ring the triangles add up to ±c, outside they cancel.
  // Summed with additive blending, this fills any polygon (holes, self-overlaps) exactly.
  fan(ring, c, out) {
    const x0 = ring[0], y0 = ring[1];
    for (let i = 2; i + 3 < ring.length; i += 2) {
      const s = Math.sign((ring[i] - x0) * (ring[i + 3] - y0) - (ring[i + 1] - y0) * (ring[i + 2] - x0));
      if (!s) continue;
      out.push(x0, y0, c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i], ring[i + 1], c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i + 2], ring[i + 3], c[0] * s, c[1] * s, c[2] * s, c[3] * s);
    }
  },
  // Thick polyline as quads (WebGL lines are 1 px); square ends overlap at the joints.
  line(pts, closed, width, c, out) {
    const n = pts.length / 2, hw = width / 2;
    for (let i = 0; i < (closed ? n : n - 1); i++) {
      const j = (i + 1) % n;
      const ax = pts[i * 2], ay = pts[i * 2 + 1], bx = pts[j * 2], by = pts[j * 2 + 1];
      const len = Math.hypot(bx - ax, by - ay);
      if (len < 1e-6) continue;
      const dx = (bx - ax) / len * hw, dy = (by - ay) / len * hw;
      const p = [ax - dx - dy, ay - dy + dx, ax - dx + dy, ay - dy - dx, bx + dx + dy, by + dy - dx, bx + dx - dy, by + dy + dx];
      for (const k of [0, 1, 2, 0, 2, 3]) out.push(p[k * 2], p[k * 2 + 1], c[0], c[1], c[2], c[3]);
    }
  },
  // Disc made of triangles.
  dot(x, y, r, c, out, seg = 16) {
    for (let i = 0; i < seg; i++) {
      const a0 = i / seg * 6.2832, a1 = (i + 1) / seg * 6.2832;
      out.push(x, y, ...c, x + Math.cos(a0) * r, y + Math.sin(a0) * r, ...c, x + Math.cos(a1) * r, y + Math.sin(a1) * r, ...c);
    }
  },
  acc: null,
  // Renders signed fans additively into a half-float target at up to 2x the canvas size
  // (sampling it back with linear filtering smooths the edges). Returns the texture.
  accumulate(arr) {
    const [w, h] = ctx.resolution, k = Math.min(2, 4096 / Math.max(w, h));
    const tw = Math.round(w * k), th = Math.round(h * k);
    if (!kit.acc) kit.acc = ctx.utils.createPingPong(tw, th, { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT });
    else if (kit.acc.width !== tw || kit.acc.height !== th) kit.acc.resize(tw, th);
    const t = kit.acc.read();
    gl.bindFramebuffer(gl.FRAMEBUFFER, t.framebuffer); gl.viewport(0, 0, tw, th);
    gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
    gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
    kit.draw(arr);
    gl.disable(gl.BLEND);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, w, h);
    return t.texture;
  },
};
const s = ctx.state;
// Three cubic curves across the canvas (units of canvas height, y up); every control point orbits.
const spec = [
  [[-0.58, 0.22], [-0.25, 0.95], [0.2, 0.05], [0.58, 0.75]],
  [[-0.58, 0.78], [-0.15, 0.05], [0.25, 0.95], [0.58, 0.25]],
  [[-0.38, 0.1], [-0.55, 0.92], [0.55, 0.92], [0.38, 0.1]],
];
s.ctrl = spec.map((pts) => pts.map(([x, y]) => ({ x, y, r: 0.04 + Math.random() * 0.06, w: 0.3 + Math.random() * 0.5, ph: Math.random() * 6.283, pin: null })));
Object.assign(s, { kit, Bezier, grab: null, wasDown: false, moved: false });
s.bg = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_fill; uniform float u_fillAlpha; uniform vec2 u_resolution;
void main(){
  vec2 q = (v_uv - 0.5) * vec2(u_resolution.x / u_resolution.y, 1.0);
  vec3 bg = mix(vec3(0.075, 0.08, 0.11), vec3(0.03, 0.03, 0.045), length(q));
  // Grid paper.
  vec2 g = abs(fract(q * 12.0 + 0.5) - 0.5) / fwidth(q * 12.0);
  bg += 0.025 * (1.0 - clamp(min(g.x, g.y), 0.0, 1.0));
  vec4 t = texture(u_fill, v_uv);
  float a = abs(t.a);
  vec3 c = a > 1e-3 ? t.rgb / t.a : vec3(0.0);
  outColor = vec4(mix(bg, c, min(a, 1.0) * u_fillAlpha), 1.0);
}`);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, kit = s.kit;
const [w, h] = ctx.resolution, A = w / h, t = ctx.time * u.u_speed;
const toPx = (p) => ({ x: (p.x + A / 2) * h, y: p.y * h });
const [mx, my] = ctx.mouse, mouse = { x: mx * w, y: (1 - my) * h };
s.moved ||= mx !== 0.5 || my !== 0.5;
if (u.u_unpin) for (const c of s.ctrl) for (const p of c) p.pin = null;
// Control points in pixels: orbiting unless pinned.
const ctrlPx = s.ctrl.map((c) => c.map((p) => p.pin ? toPx(p.pin) : toPx({ x: p.x + Math.cos(t * p.w + p.ph) * p.r, y: p.y + Math.sin(t * p.w * 1.3 + p.ph) * p.r })));
// Drag: grab the nearest control point within reach, pin it where it is released.
if (ctx.mouseDown && !s.wasDown) {
  let best = 0.05 * h;
  s.grab = null;
  ctrlPx.forEach((c, i) => c.forEach((p, j) => { const d = Math.hypot(p.x - mouse.x, p.y - mouse.y); if (d < best) { best = d; s.grab = [i, j]; } }));
}
if (!ctx.mouseDown) s.grab = null;
s.wasDown = ctx.mouseDown;
if (s.grab) {
  const [i, j] = s.grab;
  s.ctrl[i][j].pin = { x: mouse.x / h - A / 2, y: mouse.y / h };
  ctrlPx[i][j] = { ...mouse };
}
const curves = ctrlPx.map((c) => new s.Bezier(c));
const cols = [u.u_colorA, u.u_colorB, u.u_colorC];
const fills = [], lines = [], dots = [];
const lw = Math.max(1, h * 0.0025);
const lut = (c, n) => { const out = []; for (const p of c.getLUT(n)) out.push(p.x, p.y); return out; };
const d = u.u_width * h * 0.01;
curves.forEach((c, i) => {
  const col = cols[i];
  // outline(d): the closed shape d px either side of the curve, as a list of curves.
  const ring = [];
  for (const piece of c.outline(d).curves) ring.push(...lut(piece, 12));
  kit.fan(ring, [col[0], col[1], col[2], 1], fills);
  kit.line(ring, true, lw * 0.8, [col[0], col[1], col[2], 0.9], lines);
  // offset(k * gap): parallel curves further out, fading.
  for (let k = 1; k <= u.u_offsets; k++) for (const side of [1, -1]) {
    const a = 0.8 * (1 - k / (u.u_offsets + 1));
    for (const piece of c.offset(side * (d + k * d * 0.6))) kit.line(lut(piece, 10), false, lw * 0.7, [col[0], col[1], col[2], a], lines);
  }
  kit.line(lut(c, 100), false, lw * 1.6, [1, 1, 1, 0.95], lines);
  // Control polygon.
  const hull = []; for (const p of ctrlPx[i]) hull.push(p.x, p.y);
  kit.line(hull, false, lw * 0.6, [1, 1, 1, 0.25], lines);
  ctrlPx[i].forEach((p, j) => kit.dot(p.x, p.y, lw * (j % 3 ? 2.2 : 3), s.grab && s.grab[0] === i && s.grab[1] === j ? [1, 1, 1, 1] : [col[0], col[1], col[2], 1], dots, 12));
});
// intersects(other): "t1/t2" pairs where two curves cross.
let hits = 0;
for (let i = 0; i < curves.length; i++) for (let j = i + 1; j < curves.length; j++) {
  for (const pair of curves[i].intersects(curves[j])) {
    const p = curves[i].get(parseFloat(pair.split("/")[0]));
    kit.dot(p.x, p.y, lw * 7, [1, 1, 1, 0.2], dots, 24);
    kit.dot(p.x, p.y, lw * 3.2, [1, 0.95, 0.6, 1], dots, 16);
    hits++;
  }
}
// project(pointer): the nearest point on each curve; show the closest one with its normal.
if (s.moved && !s.grab) {
  let best = null;
  curves.forEach((c) => { const p = c.project(mouse); if (!best || p.d < best.p.d) best = { c, p }; });
  const { c, p } = best, n = c.normal(p.t);
  kit.line([mouse.x, mouse.y, p.x, p.y], false, lw * 0.6, [1, 1, 1, 0.4], lines);
  kit.line([p.x - n.x * d * 2, p.y - n.y * d * 2, p.x + n.x * d * 2, p.y + n.y * d * 2], false, lw, [1, 1, 1, 0.8], lines);
  kit.dot(p.x, p.y, lw * 3, [1, 1, 1, 1], dots, 16);
}
const fillTex = kit.accumulate(fills);
gl.useProgram(s.bg);
ctx.utils.bindTexture(s.bg, "u_fill", fillTex, 0);
ctx.utils.drawFullscreen(s.bg, { u_fillAlpha: u.u_fill });
gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
kit.draw(lines); kit.draw(dots);
gl.disable(gl.BLEND);
ctx.publish("intersections", hits);
